from pathlib import Path
p=Path('public/js/dashboard-concessionario.js')
s=p.read_text()
old='''    localStorage.setItem("veicolo_km", km);\n\n    window.location.href = "/risultati.html";\n  }'''
new='''    localStorage.setItem("veicolo_km", km);\n\n    mostraRisultatiInline(config);\n  }\n\n  function getVeicoloInline() {\n    return {\n      targa: localStorage.getItem("veicolo_targa") || localStorage.getItem("targa") || "",\n      modello: localStorage.getItem("veicolo_modello") || "",\n      anno: localStorage.getItem("veicolo_anno") || "",\n      km: localStorage.getItem("veicolo_km") || ""\n    };\n  }\n\n  function garanziaCompatibileInline(g) {\n    const v = getVeicoloInline();\n    if (String(g.stato || "attiva").toLowerCase() === "sospesa") return false;\n    if (Number(g.limiti_attivi || 0) !== 1) return true;\n    const kmVeicolo = Number(v.km || 0);\n    const annoVeicolo = Number(v.anno || 0);\n    if (g.limite_km && kmVeicolo > Number(g.limite_km)) return false;\n    if (g.limite_immatricolazione && annoVeicolo < Number(g.limite_immatricolazione)) return false;\n    return true;\n  }\n\n  function scegliGaranziaInline(garanzia) {\n    localStorage.setItem("garanziaSelezionata", JSON.stringify(garanzia));\n    window.location.href = "/checkout.html";\n  }\n\n  async function mostraRisultatiInline(config) {\n    const targetId = config.resultsId || "cmpInlineResults";\n    const box = document.getElementById(targetId);\n    if (!box) return;\n\n    const v = getVeicoloInline();\n    box.classList.add("open");\n    box.innerHTML = `\n      <div class="inline-results-head">\n        <div>\n          <span class="badge light">Soluzioni compatibili</span>\n          <h2>Garanzie disponibili per ${v.targa}</h2>\n          <p>${v.modello} • ${v.anno} • ${formatKm(v.km)}</p>\n        </div>\n        <div class="inline-loader">Caricamento...</div>\n      </div>\n    `;\n\n    try {\n      const res = await fetch("/api/garanzie");\n      const data = await res.json();\n      if (!res.ok) throw new Error(data.error || "Errore caricamento garanzie");\n      const lista = data.filter(garanziaCompatibileInline).sort((a,b)=>Number(a.prezzo||0)-Number(b.prezzo||0));\n\n      if (!lista.length) {\n        box.innerHTML = `\n          <div class="inline-results-head">\n            <div><span class="badge light">0 risultati</span><h2>Nessuna garanzia compatibile</h2><p>Non abbiamo trovato soluzioni compatibili con i dati inseriti. Modifica i dati del veicolo e riprova.</p></div>\n          </div>\n        `;\n        return;\n      }\n\n      box.innerHTML = `\n        <div class="inline-results-head">\n          <div>\n            <span class="badge light">${lista.length} risultat${lista.length === 1 ? "o" : "i"}</span>\n            <h2>Soluzioni compatibili</h2>\n            <p>${v.targa} • ${v.modello} • ${v.anno} • ${formatKm(v.km)}</p>\n          </div>\n        </div>\n        <div class="inline-results-grid">\n          ${lista.map(g => `\n            <article class="inline-warranty-card">\n              <div class="warranty-main">\n                <div class="warranty-topline"><span class="compatibility">✓ Compatibile</span><span class="brand-pill">${g.brand || "Partner"}</span></div>\n                <h3>${g.nome || "Garanzia"}</h3>\n                <p>${g.descrizione || "Soluzione di garanzia disponibile per il veicolo selezionato."}</p>\n                <div class="warranty-mini-grid">\n                  <span><small>Durata</small><strong>${g.durata || "—"} mesi</strong></span>\n                  <span><small>Stato</small><strong>${g.stato || "attiva"}</strong></span>\n                  <span><small>Documento</small><strong>${g.pdf_url ? "PDF" : "N/D"}</strong></span>\n                </div>\n              </div>\n              <aside class="warranty-price-box">\n                <small>Prezzo base</small>\n                <strong>${euro(g.prezzo || 0)}</strong>\n                <button class="hero-btn primary btnScegliGaranziaInline" type="button" data-id="${g.id}">Scegli</button>\n              </aside>\n            </article>\n          `).join("")}\n        </div>\n      `;\n\n      box.querySelectorAll(".btnScegliGaranziaInline").forEach(button => {\n        button.addEventListener("click", () => {\n          const garanzia = lista.find(g => Number(g.id) === Number(button.dataset.id));\n          if (garanzia) scegliGaranziaInline(garanzia);\n        });\n      });\n      box.scrollIntoView({ behavior: "smooth", block: "start" });\n    } catch (error) {\n      box.innerHTML = `<div class="empty-state">${error.message || "Errore di connessione al server."}</div>`;\n    }\n  }'''
if old not in s: print('old not found js')
s=s.replace(old,new)
p.write_text(s)

# Add results container and CSS to dashboard-concessionario
p=Path('public/dashboard-concessionario.html')
s=p.read_text()
css='''\n    /* Risultati comparatore integrati nella dashboard */\n    .inline-results { display:none; margin-top:18px; }\n    .inline-results.open { display:block; }\n    .inline-results-head {\n      display:flex; align-items:flex-end; justify-content:space-between; gap:18px; flex-wrap:wrap;\n      padding:24px 26px; margin-bottom:14px; border-radius:24px; color:#fff;\n      background:radial-gradient(circle at 92% 18%, rgba(24,180,90,.30), transparent 32%), linear-gradient(135deg,#071d49 0%,#123477 55%,#255fba 100%);\n      box-shadow:0 22px 55px rgba(7,29,73,.16);\n    }\n    .inline-results-head h2 { margin:0 0 6px; color:#fff; font-size:28px; font-weight:950; }\n    .inline-results-head p { margin:0; color:rgba(255,255,255,.78); font-weight:750; }\n    .inline-results-head .badge.light { background:rgba(255,255,255,.14)!important; color:#fff!important; border:1px solid rgba(255,255,255,.18)!important; }\n    .inline-loader { font-weight:950; background:rgba(255,255,255,.12); border:1px solid rgba(255,255,255,.18); border-radius:999px; padding:10px 14px; }\n    .inline-results-grid { display:grid; gap:14px; }\n    .inline-warranty-card {\n      display:grid; grid-template-columns:minmax(0,1fr) 220px; gap:18px; align-items:stretch;\n      background:linear-gradient(135deg,#fff 0%,#f8fbff 100%); border:1px solid #e2eaf5; border-radius:24px;\n      padding:20px; box-shadow:0 14px 32px rgba(7,29,73,.07); position:relative; overflow:hidden;\n    }\n    .inline-warranty-card::before { content:""; position:absolute; inset:0 auto 0 0; width:5px; background:linear-gradient(180deg,#18b45a,#4f8cff,#7b61ff); }\n    .warranty-topline { display:flex; gap:10px; flex-wrap:wrap; align-items:center; margin-bottom:10px; }\n    .compatibility,.brand-pill { display:inline-flex; border-radius:999px; padding:7px 10px; font-size:12px; font-weight:950; }\n    .compatibility { background:#eafaf1; color:#0fa34f; }\n    .brand-pill { background:#eef6ff; color:#2563eb; }\n    .inline-warranty-card h3 { margin:0 0 8px; color:#071d49; font-size:22px; font-weight:950; }\n    .inline-warranty-card p { margin:0 0 14px; color:#64748b; line-height:1.55; }\n    .warranty-mini-grid { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:10px; }\n    .warranty-mini-grid span { background:#fff; border:1px solid #edf2f7; border-radius:15px; padding:11px; }\n    .warranty-mini-grid small { display:block; color:#64748b; font-size:10px; font-weight:950; text-transform:uppercase; margin-bottom:5px; }\n    .warranty-mini-grid strong { color:#071d49; font-weight:950; }\n    .warranty-price-box { display:flex; flex-direction:column; justify-content:space-between; gap:12px; padding:16px; border-radius:20px; background:#071d49; color:#fff; }\n    .warranty-price-box small { color:#cfe0ff; font-weight:900; text-transform:uppercase; }\n    .warranty-price-box strong { font-size:28px; font-weight:950; }\n    @media(max-width:800px){ .inline-warranty-card{grid-template-columns:1fr}.warranty-mini-grid{grid-template-columns:1fr}.warranty-price-box{background:#f8fbff;color:#071d49;border:1px solid #e2eaf5} }\n'''
s=s.replace('</style>', css+'\n  </style>')
s=s.replace('''          <div id="cmpSearchError" class="search-error"></div>\n        </div>\n      </section>''','''          <div id="cmpSearchError" class="search-error"></div>\n        </div>\n        <div id="cmpInlineResults" class="inline-results"></div>\n      </section>''')
p.write_text(s)
